package org.example;
import javafx.fxml.FXML; import javafx.scene.control.*;
public class LoginController { @FXML private TextField signInEmail,signInPasswordVisible,signUpName,signUpEmail,signUpAddress,signUpPasswordVisible; @FXML private PasswordField signInPassword,signUpPassword; @FXML private Button signInEyeButton,signUpEyeButton; private boolean inVisible,upVisible;
 @FXML private void toggleSignInPassword(){if(inVisible) signInPassword.setText(signInPasswordVisible.getText()); else signInPasswordVisible.setText(signInPassword.getText());inVisible=!inVisible;signInPassword.setVisible(!inVisible);signInPassword.setManaged(!inVisible);signInPasswordVisible.setVisible(inVisible);signInPasswordVisible.setManaged(inVisible);signInEyeButton.setText(inVisible?"🙈":"👁");}
 @FXML private void toggleSignUpPassword(){if(upVisible) signUpPassword.setText(signUpPasswordVisible.getText()); else signUpPasswordVisible.setText(signUpPassword.getText());upVisible=!upVisible;signUpPassword.setVisible(!upVisible);signUpPassword.setManaged(!upVisible);signUpPasswordVisible.setVisible(upVisible);signUpPasswordVisible.setManaged(upVisible);signUpEyeButton.setText(upVisible?"🙈":"👁");}
 @FXML private void signIn(){try{Customer c=AppServices.BOOKSTORE.signIn(signInEmail.getText(),inVisible?signInPasswordVisible.getText():signInPassword.getText());StoreApp.showStore(c);}catch(Exception e){e.printStackTrace();alert(e.getClass().getSimpleName()+": "+(e.getMessage()==null?"Unexpected error":e.getMessage()));}}
 @FXML private void signUp(){try{Customer c=AppServices.BOOKSTORE.signUp(signUpName.getText(),signUpEmail.getText(),upVisible?signUpPasswordVisible.getText():signUpPassword.getText(),signUpAddress.getText());StoreApp.showStore(c);}catch(Exception e){e.printStackTrace();alert(e.getClass().getSimpleName()+": "+(e.getMessage()==null?"Unexpected error":e.getMessage()));}}
 private void alert(String m){Alert a=new Alert(Alert.AlertType.INFORMATION);a.setTitle("Online Bookstore");a.setHeaderText(null);a.setContentText(m==null?"Something went wrong.":m);a.showAndWait();} }